from pathlib import Path
import json,pandas as pd
ROOT=Path(__file__).resolve().parents[1];R=ROOT/'results'
def j(n):return json.loads((R/n).read_text())
s=(ROOT/'report/main.template.tex').read_text();w=j('warehouse_checks.json');st=j('staging_quality.json');ex=j('source_audit.json');f=j('feature_run.json');m=j('session_mining.json');cards=j('card_mining.json');b=pd.DataFrame(j('benchmarks.json'))
etl=f"The automated extraction scan took {ex['seconds']:.1f} seconds (download time excluded because the pinned originals were already present); Spark staging took {st['seconds']:.1f} seconds; the warehouse build and validation took {w['database_build_seconds']:.1f} seconds; feature preparation took {f['seconds']:.1f} seconds; and both-source mining took {cards['seconds_total_mining']:.1f} seconds. The full six-task Airflow run completed in 277.4 seconds, including orchestration and benchmark overhead. These are measured elapsed times on this host, not distributed-throughput claims."
p=b.pivot(index='query',columns='strategy',values='median_seconds');rows=[]
for name,row in p.iterrows():
 n=int(b.loc[b['query'].eq(name),'rows'].iloc[0]);rows.append(f"{name[:2].upper()} & {row['native']*1000:.1f} & {row['secondary_indexes']*1000:.1f} & {row['date_partitioned_parquet']*1000:.1f} & {n:,} \\\\")
bench='\n'.join(rows)
interp=f"Date partitions reduce Q5's median from {p.loc['q5_session_rank','native']*1000:.1f} to {p.loc['q5_session_rank','date_partitioned_parquet']*1000:.1f} ms, while the full-month Q1 rises from {p.loc['q1_category_rollup','native']*1000:.1f} to {p.loc['q1_category_rollup','date_partitioned_parquet']*1000:.1f} ms. Q4 also benefits modestly. Secondary indexes do not consistently help these scan-and-aggregate workloads. Index construction took {j('index_build.json')['seconds']:.2f} s and partition export took {j('partition_build.json')['seconds']:.2f} s; these preparation costs are not hidden inside the timed SELECTs."
session=f"The final Isolation Forest flags {m['test_flagged']:,}/{m['test_sessions']:,} test visits ({100*m['test_flagged']/m['test_sessions']:.3f}\\%) at threshold {m['if_threshold_train_q995']:.4f}. The velocity baseline flags {m['velocity_test_flagged']:,} test visits above {m['velocity_threshold_train_q995']:.1f} transitions/minute. These counts compare review workload, not fraud detection accuracy. The selected clustering has $k={m['selected_k']}$, validation silhouette {m['validation_silhouette']:.3f}, and test silhouette {m['test_silhouette']:.3f}."
cp=pd.read_csv(R/'cluster_profiles.csv');clusters='\n'.join(f"{int(x.cluster)} & {int(x.sessions):,} & {x.events:.1f} & {x.products:.1f} & {x.duration:.1f} & {x.purchase_rate:.3f} \\\\" for x in cp.itertuples())
ci='Cluster 0 consists of singleton visits. Clusters 1 and 2 contain longer, multi-product browsing, with cluster 2 exploring more products on average. Cluster 3 has the highest purchase-event fraction and fewer distinct products; cluster 4 represents brief browsing. These descriptive names are interpretations of aggregate profiles, not verified intent. The highest mean anomaly-flag rate occurs in cluster 2, but this alone does not validate the proposal\'s cluster-relative anomaly hypothesis.'
names={'isolation_forest':'Isolation Forest','logistic_regression':'Logistic regression','random_forest':'Random Forest','amount_baseline':'Amount baseline'}
card='\n'.join(names[x['model']]+' & '+' & '.join(f"{x[k]:.3f}" for k in ['test_average_precision','test_roc_auc','test_precision','test_recall','test_f1'])+' \\\\' for x in cards['metrics'])
boot=j('bootstrap.json');boottext='A 100-replicate stratified bootstrap on the fixed test set gives percentile 95\\% AP intervals of '+', '.join(f"{x['low_95']:.3f}--{x['high_95']:.3f} for {names[x['model']]}" for x in boot)+'. These conditional intervals hold test class counts fixed and assume independent resampling within each class. They do not incorporate training variability, entity dependence, or future distribution shift; overlapping intervals do not establish a statistically significant ordering between the supervised models. Only 75 test frauds are available.'
for key,value in {'ETL':etl,'BENCH':bench,'BENCHINTERPRET':interp,'SESSION':session,'CLUSTERS':clusters,'CLUSTERINTERPRET':ci,'CARD':card,'BOOTSTRAP':boottext}.items():s=s.replace('@@'+key+'@@',value)
assert '@@' not in s
(ROOT/'report/main.tex').write_text(s)
